**Free

Dcl-S wFavoriteColours Char(10) DIM(3) ;
Dcl-S wColour Char(10) ;
Dcl-S wNumber Packed(2 : 0) ;

// Assign data to an Array using %LIST
wFavoriteColours = %LIST('RED'
                         :'GREEN'
                         :'BLUE') ;

// Loop through an array using FOR-EACH loop
FOR-EACH wColour IN wFavoriteColours ;
  Dsply wColour ;
ENDFOR ;

// Loop through the values provided by %LIST using FOR-EACH
FOR-EACH wColour IN %LIST('BLACK' : 'WHITE' : 'YELLOW') ;
  Dsply wColour ;
ENDFOR ;

// Loop throigh numeric values provided by %LIST using FOR-EACH
FOR-EACH wNumber IN %LIST(10 : 12 : 15) ;
  Dsply wNumber ;
ENDFOR ;

// Loop through Subarray using %SUBARR and FOR-EACH
FOR-EACH wColour IN %SUBARR(wFavoriteColours : 2 : 2) ;
  Dsply wColour ;
ENDFOR ;

*InLr = *On ;

