Dcl-Ds EmployeeDetails Qualified ;
  Name Char(30) ;
  Age Packed(2 : 0) ;
End-Ds ;

Dcl-Ds EmployeeDetailsArray LikeDs(EmployeeDetails) DIM(10) ;

FOR-EACH EmployeeDetails IN EmployeeDetailsArray ;
  Dsply EmployeeDetails.Name ;
  Dsply EmployeeDetails.Age ;
ENDFOR ;

