  Dcl-S wNumber Packed(2 : 0) Inz(10) ;
  Dcl-S wString Char(2) Inz('AB') ;

  If wNumber IN %Range(1 : 15) ;
    Dsply wNumber ;
  EndIf ;

  If wString IN %Range('AA' : 'BB') ;
    Dsply wString ;
  EndIf ;

  Dow wNumber IN %Range(1 : 15) ;
    Dsply wNumber ;
    wNumber += 1 ;
  EndDo ;

